from dataclasses import dataclass, asdict, fields

@dataclass
class UserRequest:
    name: str
    email: str
    password: str

@dataclass
class UserResponse:
    id: int
    name: str
    email: str


def validate(model_cls, raw):
    kwargs = {}
    for f in fields(model_cls):
        if f.name not in raw:
            return None, {"status": 422, "error": f"missing field {f.name!r}"}
        value = raw[f.name]
        if not isinstance(value, f.type):
            return None, {"status": 422, "error": f"wrong type for {f.name!r}"}
        kwargs[f.name] = value
    return model_cls(**kwargs), None


def to_response(response_cls, source_dict):
    allowed = {f.name for f in fields(response_cls)}
    return response_cls(**{k: v for k, v in source_dict.items() if k in allowed})


raw_input = {"name": "Ana", "email": "ana@example.com", "password": "secret123"}
user, error = validate(UserRequest, raw_input)
print(error or asdict(user))

stored = {"id": 1, "name": user.name, "email": user.email, "password_hash": "***"}
response = to_response(UserResponse, stored)
print(asdict(response))

bad_input = {"name": "Beto", "email": "beto@example.com"}
_, error = validate(UserRequest, bad_input)
print(error)
